def gradient_at(value):
    with tf.device("/CPU:0"):
        weight = tf.Variable(value, dtype=tf.float64)
        with tf.GradientTape() as tape:
            loss = tf.square(weight - 2.0)
        gradient = tape.gradient(loss, weight)
    if gradient is None:
        raise ValueError("recorded scalar path is disconnected")
    return float(loss.numpy()), float(gradient.numpy())

    return {"loss": 4.0, "gradient": -4.0, "optimum_gradient": 0.0}


if __name__ == "__main__":
    print(verify())

# Exercise 6: Reject undefined cosine
def cosine(x, y):
    x, y = np.asarray(x), np.asarray(y)
    den = np.linalg.norm(x) * np.linalg.norm(y)
    if x.shape != y.shape or not np.isfinite(den) or den == 0:
        raise ValueError("finite nonzero vectors")
    return float(x @ y / den)

try:
    cosine([0, 0], [1, 1])
except ValueError:
    pass
else:
    raise AssertionError("undefined cosine accepted")

    return {"checks": 6, "status": "passed"}


if __name__ == "__main__":
    print(verify())
